require('dotenv').config();const controller=require('../controllers/CertificadoCliente.controller');const {sql}=require('../DB/dbConection');
function respuesta(){const salida={codigo:200,cuerpo:null,status(codigo){this.codigo=codigo;return this;},json(cuerpo){this.cuerpo=cuerpo;return cuerpo;}};return salida;}
(async()=>{try{const listado=respuesta();await controller.listar({params:{proyectoId:'8'}},listado);if(listado.codigo!==200||!Array.isArray(listado.cuerpo))throw new Error(`Listado fallo: ${JSON.stringify(listado)}`);const certificado=listado.cuerpo[0];if(!certificado)throw new Error('No existe certificado vigente para validar');if(!['PENDIENTE','PAGADO_PARCIAL','PAGADO'].includes(certificado.estado_pago))throw new Error('Estado de pago invalido');const detalle=respuesta();await controller.detalle({params:{proyectoId:'8',certificadoId:String(certificado.certificado_cliente_id)}},detalle);if(detalle.codigo!==200||!Array.isArray(detalle.cuerpo.pagos))throw new Error(`Detalle fallo: ${JSON.stringify(detalle)}`);console.log(JSON.stringify({certificado_cliente_id:certificado.certificado_cliente_id,estado_pago:certificado.estado_pago,total:certificado.total,total_cobrado:certificado.total_cobrado,saldo_cobro:certificado.saldo_cobro,pagos_asociados:detalle.cuerpo.pagos.length},null,2));}finally{await sql.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
